def f(x,y):
    if x<y or x==12 or x==15: return 0
    if x==y: return 1
    res = f(x-1,y)
    if x%2==0: res+=f(x//2,y)
    if x%3==0: res+=f(x//3,y)
    return res
print(f(19,1))  # 43

