Используем кэширование и счётчик встреч запрещённых чисел.
Код:
from functools import cache
@cache
def Rr(m, f):
    if m==20 or m==8: f+=1
    if f>1 or m<3: return 0
    if m==3: return 1
    return Rr(m-1,f)+Rr(m-3,f)+Rr(m//2,f)
print(Rr(31,0))  # 47315

